function highlightParts(text, term) {
  const parts = [];
  const lower = text.toLowerCase();
  const needle = term.toLowerCase();
  let from = 0;
  let at = needle === "" ? -1 : lower.indexOf(needle);
  while (at !== -1) {
    parts.push(text.slice(from, at));
    parts.push({ mark: text.slice(at, at + needle.length) });
    from = at + needle.length;
    at = lower.indexOf(needle, from);
  }
  parts.push(text.slice(from));
  return parts.filter((p) => p !== "");
}

const show = (parts) => parts.map((p) => (typeof p === "string" ? p : `[${p.mark}]`)).join("");
console.log(show(highlightParts("Clean the flat, then clean the car", "clean")));
console.log(show(highlightParts("<b>Invoice</b>", "invoice")));
console.log(highlightParts("Buy detergent", "").length);

