questions.solution:
function checkTitle(raw) {
  const title = String(raw).trim();
  if (title === "") return { error: "A task needs a title." };
  if (title.length > 120) return { error: "Keep the title under 120 characters." };
  return { title };
}

console.log(checkTitle("  Clean the Okafor flat  "));
console.log(checkTitle("   "));
console.log(checkTitle("x".repeat(121)));
console.log(checkTitle("Fix <sink>"));
